function getAuthDurationMs(request: FastifyRequest): number | undefined {
  return (request as any)[AUTH_DURATION_MS] as number | undefined;
}

function setVerifiedUser(
  request: FastifyRequest,
  verified: VerifiedAuthClaims,
  durationMs: number
): void {
